#include <stdio.h>

/* teste do desafio notas-na-tela — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: o teste chama a funcao do aluno e captura o stdout no
   proprio cenario (freopen para arquivo temporario, fflush, leitura de
   volta). Cada cenario tem o SEU arquivo de captura. Duas turmas: a
   primeira e a ultima nota mudam, as tres do meio nao. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void notasNaTela(int primeira, int ultima);

SM_TEST(as_cinco_notas_da_turma_a) {
    freopen("sm_saida_1.tmp", "w", stdout);
    notasNaTela(10, 2);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a gaveta 0 da turma A", linha, "10\n",
              "a primeira nota entregue vai para a gaveta 0 e sai na primeira linha");
    fgets(linha, 80, f);
    checa_str("a gaveta 1 da turma A", linha, "8\n",
              "a segunda gaveta guarda o 8 do inicializador");
    fgets(linha, 80, f);
    checa_str("a gaveta 2 da turma A", linha, "6\n",
              "a terceira gaveta guarda o 6 do inicializador");
    fgets(linha, 80, f);
    checa_str("a gaveta 3 da turma A", linha, "9\n",
              "a quarta gaveta guarda o 9 do inicializador");
    fgets(linha, 80, f);
    checa_str("a gaveta 4 da turma A", linha, "2\n",
              "a ultima nota entregue vai para a gaveta 4, a quinta e ultima");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a caixa tem cinco gavetas: a saida acaba na quinta linha");
    fclose(f);
}

SM_TEST(as_cinco_notas_da_turma_b) {
    freopen("sm_saida_2.tmp", "w", stdout);
