#include <stdio.h>

void notasNaTela(int primeira, int ultima) {
    int notas[5] = {primeira, 8, 6, 9, ultima};
    printf("%d\n", notas[0]);
    printf("%d\n", notas[1]);
    printf("%d\n", notas[2]);
    printf("%d\n", notas[3]);
    printf("%d\n", notas[4]);
}
